import{_ as t,o as a,c as l,a2 as o}from"./chunks/framework.BHqQo5Fe.js";const _=JSON.parse('{"title":"你好，世界","description":"为什么我要重新搭一个博客，以及这个站点打算写些什么。","frontmatter":{"title":"你好，世界","date":"2026-08-24","description":"为什么我要重新搭一个博客，以及这个站点打算写些什么。","cover":"/covers/hello.svg","tags":["随笔","建站"],"categories":["生活"],"prev":false,"next":{"text":"用 VitePress 搭一个博客","link":"/posts/vitepress-setup"}},"headers":[],"relativePath":"posts/hello-world.md","filePath":"posts/hello-world.md"}'),s={name:"posts/hello-world.md"};function r(i,e,n,p,d,h){return a(),l("div",null,[...e[0]||(e[0]=[o('<p>这是这个博客的第一篇文章。与其一上来就讲技术，不如先回答一个更基础的问题：为什么还要写博客？</p><h2 id="为什么还要写博客" tabindex="-1">为什么还要写博客 <a class="header-anchor" href="#为什么还要写博客" aria-label="Permalink to &quot;为什么还要写博客&quot;">​</a></h2><p>短视频和碎片化阅读的时代，写长文看起来是件不划算的事。但对我而言，写博客解决的问题很具体：</p><ol><li><strong>把「好像懂了」变成「确实懂了」</strong>。能讲清楚，才算真的理解。</li><li><strong>给未来的自己留档</strong>。半年前踩过的坑，半年后一定忘得一干二净。</li><li><strong>建立自己的信息索引</strong>。搜索是别人的排序，博客是我的排序。</li></ol><h2 id="这里会写什么" tabindex="-1">这里会写什么 <a class="header-anchor" href="#这里会写什么" aria-label="Permalink to &quot;这里会写什么&quot;">​</a></h2><p>大致会有三类内容：</p><ul><li><strong>工程实践</strong>：构建工具、组件设计、性能优化，偏「怎么做」。</li><li><strong>原理笔记</strong>：读源码、读规范后的整理，偏「为什么」。</li><li><strong>杂谈</strong>：效率工具、学习方法、偶尔的碎碎念。</li></ul><p>技术类文章会尽量做到：给结论、给最小可复现的例子、给参考链接。不确定的地方会明确标注，而不是用含糊的措辞糊过去。</p><h2 id="关于这个站点" tabindex="-1">关于这个站点 <a class="header-anchor" href="#关于这个站点" aria-label="Permalink to &quot;关于这个站点&quot;">​</a></h2><p>这个博客基于 VitePress 搭建，源码托管在 GitHub，构建产物发布到 GitHub Pages。</p><p>它有几个我很在意的细节：</p><ul><li>支持浅色 / 深色模式切换，深色下不牺牲对比度</li><li>手机上导航收进抽屉，不挤占正文空间</li><li>图片懒加载，首屏尽量轻</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>先把「基础设施」写完：建站过程、配色与深色模式、性能优化清单。然后就进入正题。</p><p>如果你也想搭一个类似的博客，可以从 <a href="/blog_pages/posts/vitepress-setup">用 VitePress 搭一个博客</a> 开始看。</p>',15)])])}const u=t(s,[["render",r]]);export{_ as __pageData,u as default};
